import itertools

# Search for combinations of exponents (a_1, ..., a_k)
# The maximum possible a_i can be bounded. 
# If a_i is large, 12a_i + 1 is small compared to p_i^a_i.
# For n = product (12a_i + 1), the number of prime factors of n is 
# at most log2(n).
# Also, the exponents of n are the a_i's.
# So sum(a_i) = omega(n) + sum(a_i - 1) ... not helpful.
# But n = product (12a_i + 1).
# Let's try k from 1 to 6.
# For each k, let's try a_i in range(1, 20).

solutions = {1}
for k in range(1, 7):
    for a in itertools.product(range(1, 20), repeat=k):
        n = 1
        for val in a:
            n *= (12 * val + 1)

        if get_exponents(n) == sorted(a, reverse=True):
            solutions.add(n)

print(sorted(list(solutions)))

