def find_solutions(max_sum_a):
    solutions = {1}
    # Use recursion to find combinations of a_i that sum to <= max_sum_a
    def generate_a(current_a, current_sum):
        # Check current combination
        if current_a:
            n = 1
            for val in current_a:
                n *= (12 * val + 1)
            if get_exponents(n) == sorted(current_a, reverse=True):
                solutions.add(n)

        if current_sum >= max_sum_a:
            return

        # To avoid permutations, we only add a_i >= last a_i
        start_val = current_a[-1] if current_a else 1
        for val in range(start_val, max_sum_a - current_sum + 1):
            generate_a(current_a + [val], current_sum + val)

    generate_a([], 0)
    return sorted(list(solutions))

print(find_solutions(20))
